// Pure transaction coordinator. No story inference and no duplicated persistent state.
function createDreamController(env, chapters) {
  const byId = Object.fromEntries(chapters.map(c => [c.id, c]));
  const empty = () => ({_时代:'未选择',_当前篇章:'',_现代锁定:false});
  let queue = Promise.resolve();
  const serial = job => { const p=queue.then(job); queue=p.catch(()=>{}); return p; };
  function state() {
    const s=env.read()?.stat_data;
    if (!s) return empty();
    return {_时代:s._时代??'未选择',_当前篇章:s._当前篇章??'',_现代锁定:s._现代锁定===true};
  }
  function canEnter(id, s=state()) {
    const c=byId[id], old=byId[s._当前篇章];
    return !!c && !(s._现代锁定&&c.era==='ancient') && (!old||c.rank>=old.rank);
  }
  async function book() {
    const names=await env.names();
    const candidates=[...new Set([names.primary,...(names.additional||[])].filter(Boolean))];
    for(const name of candidates){
      const entries=await env.getBook(name);
      const marked=entries.filter(e=>/【HXY_TIMELINE:[AM]\d{2}】/.test(e.name||e.comment||''));
      if(!marked.length)continue;
      if(marked.length!==21||chapters.some(c=>marked.filter(e=>(e.name||e.comment||'').includes(`【HXY_TIMELINE:${c.id}】`)).length!==1))
        throw Error('缘卷索引不完整，请重新导入正式卡内世界书。');
      return {name,entries};
    }
    throw Error('尚未找到绑定的梦灯笼世界书，请在角色设置绑定内嵌世界书。');
  }
  function planned(entries,id) {
    return entries.map(e=>/【HXY_TIMELINE:[AM]\d{2}】/.test(e.name||e.comment||'')
      ? {...e,enabled:!!id&&(e.name||e.comment||'').includes(`【HXY_TIMELINE:${id}】`)} : e);
  }
  async function switchTo(id) {
    if(!env.ready())throw Error('梦灯正在点亮，变量系统就绪后即可入梦。');
    const token=env.context(),s=state();
    if(!canEnter(id,s))throw Error('这段缘分仅供历史观忆，不能返回。');
    const target=byId[id],{name,entries}=await book();
    if(token!==env.context())throw Error('聊天已经切换，请在当前聊天重新选择。');
    const next=planned(entries,id);
    await env.writeBook(name,next); // One worldbook write, then MVU commit.
    try {
      if(token!==env.context())throw Error('聊天已切换，入梦未提交。');
      const data=structuredClone(env.read());
      data.stat_data={_时代:target.era==='ancient'?'古代':'现代',_当前篇章:id,_现代锁定:s._现代锁定||target.era==='modern'};
      await env.writeData(data);
    } catch(error) {
      if(token===env.context())await env.writeBook(name,entries);
      throw error;
    }
    return state();
  }
  async function repair() {
    if(!env.ready())return false;
    const token=env.context(),s=state();
    if(s._当前篇章&&!byId[s._当前篇章])throw Error('当前缘卷编号无法识别，请检查存档。');
    const {name,entries}=await book();
    if(token!==env.context())return false;
    const next=planned(entries,s._时代==='未选择'?'':s._当前篇章);
    if(entries.some((e,i)=>e.enabled!==next[i].enabled)){await env.writeBook(name,next);return true;}
    return false;
  }
  return {state,canEnter,enter:id=>serial(()=>switchTo(id)),heal:()=>serial(repair)};
}

